-- Do NOT run this whole file as root: that does not test restricted accounts.
-- Connect as each named localhost user, using the password generated by 04_security.sql.
-- Run each statement separately. Expected denial errors are successful negative tests.

-- SECTION A: cf_patient_demo (SELECT only through its own-record view).
SELECT USER(), CURRENT_ROLE();
SELECT * FROM crownfield_eye_hospital.v_patient_own_appointments;
-- Expected: appointment 1 / P001 only.
SELECT * FROM crownfield_eye_hospital.appointment;
-- Expected: access denied (1142).
UPDATE crownfield_eye_hospital.appointment SET status = 'Cancelled' WHERE appointment_id = -1;
-- Expected: UPDATE denied; nonexistent ID ensures no mutation even if run by mistake as root.
SELECT * FROM crownfield_eye_hospital.patient_account;
-- Expected: access denied, preventing self-remapping to another patient.

-- SECTION B: cf_reception_demo.
SELECT USER(), CURRENT_ROLE();
SELECT patient_id, first_name, last_name, phone FROM crownfield_eye_hospital.patient;
-- Expected: 14 patients after the supplied Appendix import.
SELECT appointment_id, appointment_date, appointment_time, status FROM crownfield_eye_hospital.appointment;
-- Expected: 15 appointments after the supplied Appendix import.
SELECT diagnosis_name FROM crownfield_eye_hospital.diagnosis;
-- Expected: access denied.
SELECT notes FROM crownfield_eye_hospital.appointment;
-- Expected: column access denied (1143).
DELETE FROM crownfield_eye_hospital.patient WHERE patient_id = 'NO_PATIENT';
-- Expected: DELETE denied; no real patient is targeted.

-- SECTION C: cf_doctor_demo.
SELECT USER(), CURRENT_ROLE();
SELECT diagnosis_name FROM crownfield_eye_hospital.diagnosis;
-- Expected: 15 diagnoses after the supplied Appendix import.
CALL crownfield_eye_hospital.get_patient_appointments('P001');
-- Expected: appointment 1.
SELECT email FROM crownfield_eye_hospital.patient;
-- Expected: column access denied; doctor has only the listed patient columns.
DELETE FROM crownfield_eye_hospital.patient WHERE patient_id = 'NO_PATIENT';
-- Expected: DELETE denied.

-- SECTION D: cf_admin_demo (data administrator, no global server administration).
SELECT USER(), CURRENT_ROLE();
SELECT COUNT(*) AS patients FROM crownfield_eye_hospital.patient;
-- Expected after the supplied Appendix import: 14.
DELETE FROM crownfield_eye_hospital.clinic WHERE clinic_id = -1;
-- Expected: permitted, 0 rows affected.
SELECT User FROM mysql.user;
-- Expected: denied; schema administrator is not MySQL root.
